"""matplotlib.backends.backend_gtk3cairo — gtk3cairo backend stub.

The shim renders every figure through plotly, so this module exists to
satisfy ``from matplotlib.backends.backend_gtk3cairo import
FigureCanvasGTK3Cairo`` imports. Saving uses plotly's native export.
"""

from matplotlib.backends._backend_helpers import (
    _make_canvas, _make_manager, _make_backend,
)


FigureCanvasGTK3Cairo = _make_canvas('FigureCanvasGTK3Cairo', 'png')
FigureManagerGTK3Cairo = _make_manager('FigureManagerGTK3Cairo')

# Aliases — every backend exposes ``FigureCanvas`` and ``FigureManager``.
FigureCanvas = FigureCanvasGTK3Cairo
FigureManager = FigureManagerGTK3Cairo

# Backend class registered with matplotlib's _Backend system.
_BackendStub = _make_backend('_BackendGTK3Cairo', FigureCanvas, FigureManager)
new_figure_manager = _BackendStub.new_figure_manager
draw_if_interactive = _BackendStub.draw_if_interactive
show = _BackendStub.show
